INSERT INTO app_settings VALUES('forecast_workflow_graph','{"version": 1, "title": "预测算法工作流", "summary": "展示目标价是怎么计算出来的，并允许在后台调整自动收敛参数。", "nodes": [{"id": "source_signals", "label": "市场信号输入", "processor": "source", "x": 32.0, "y": 48.0, "params": {"source_key": "signals_bundle"}}, {"id": "source_volatility", "label": "波动率输入", "processor": "source", "x": 32.0, "y": 188.0, "params": {"source_key": "volatility_context"}}, {"id": "source_backtest", "label": "回测输入", "processor": "source", "x": 32.0, "y": 328.0, "params": {"source_key": "backtest_context"}}, {"id": "source_confidence", "label": "置信度输入", "processor": "source", "x": 32.0, "y": 468.0, "params": {"source_key": "confidence_context"}}, {"id": "raw_signal", "label": "原始信号", "processor": "raw_signal", "x": 312.0, "y": 48.0, "params": {}}, {"id": "predicted_clip", "label": "总涨幅限幅", "processor": "clip", "x": 580.0, "y": 48.0, "params": {"limit_key": "predicted_change_limit"}}, {"id": "volatility_cap", "label": "波动率约束", "processor": "volatility_cap", "x": 848.0, "y": 118.0, "params": {"multiplier_key": "volatility_cap_multiplier"}}, {"id": "backtest_shrink", "label": "回测收缩", "processor": "backtest_blend", "x": 1116.0, "y": 258.0, "params": {"weight_key": "backtest_weight"}}, {"id": "confidence_penalty", "label": "置信度惩罚", "processor": "confidence_guard", "x": 1384.0, "y": 398.0, "params": {"floor_key": "confidence_floor", "range_key": "range_bound_multiplier", "scale_key": "confidence_penalty_scale"}}, {"id": "final_output", "label": "最终目标涨跌幅", "processor": "output", "x": 1652.0, "y": 398.0, "params": {}}, {"id": "volatility_cap_1780989130995_11", "label": "波动率约束", "processor": "volatility_cap", "x": 460.19097222222223, "y": 229.45746527777777, "params": {"multiplier_key": ""}}], "edges": [{"id": "edge_signals_raw", "from": "source_signals", "to": "raw_signal"}, {"id": "edge_raw_clip", "from": "raw_signal", "to": "predicted_clip"}, {"id": "edge_clip_vol", "from": "predicted_clip", "to": "volatility_cap"}, {"id": "edge_vol_ctx", "from": "source_volatility", "to": "volatility_cap"}, {"id": "edge_vol_backtest", "from": "volatility_cap", "to": "backtest_shrink"}, {"id": "edge_backtest_ctx", "from": "source_backtest", "to": "backtest_shrink"}, {"id": "edge_backtest_conf", "from": "backtest_shrink", "to": "confidence_penalty"}, {"id": "edge_conf_ctx", "from": "source_confidence", "to": "confidence_penalty"}, {"id": "edge_conf_output", "from": "confidence_penalty", "to": "final_output"}, {"id": "edge_1780989136340_10", "from": "volatility_cap_1780989130995_11", "to": "volatility_cap"}], "tuning": {"factor_score_clip": 8.0, "factor_signal_limit": 12.0, "momentum_signal_limit": 18.0, "predicted_change_limit": 35.0, "fundamental_adjustment_limit": 3.0, "volatility_cap_multiplier": 1.35, "backtest_weight": 0.55, "confidence_penalty_scale": 0.2, "confidence_floor": 45.0, "range_bound_multiplier": 0.85}}','2026-06-09 15:12:25');
